$ErrorActionPreference = 'Stop'
$report = Join-Path ([Environment]::GetFolderPath('Desktop')) ('M1M_TF3A_BUILD_' + (Get-Date -Format 'yyyyMMdd_HHmmss') + '.txt')
$taskRoot = Join-Path ([IO.Path]::GetTempPath()) ('m1m-tf3a-build-' + [Guid]::NewGuid().ToString('N'))
function Run-Checked {
  param([string]$Program, [string[]]$Arguments)
  & $Program @Arguments
  if ($LASTEXITCODE -ne 0) { throw ('Falha em ' + $Program + '; codigo ' + $LASTEXITCODE) }
}
Start-Transcript -Path $report | Out-Null
try {
  foreach ($program in @('git','node','npm.cmd','docker')) {
    if (-not (Get-Command $program -ErrorAction SilentlyContinue)) { throw ('Dependencia ausente: ' + $program + '. Nada sera instalado automaticamente.') }
  }
  $dockerType = & docker info --format '{{.OSType}}'
  if ($LASTEXITCODE -ne 0 -or $dockerType.Trim() -ne 'linux') { throw 'Docker precisa estar disponivel no modo Linux containers. Nenhum servico sera iniciado pelo script.' }
  $nodeMajor = & node --version
  if ($LASTEXITCODE -ne 0 -or -not $nodeMajor.Trim().StartsWith('v24.')) { throw 'Este build exige Node 24 local; nenhuma atualizacao automatica sera feita.' }
  New-Item -ItemType Directory -Path $taskRoot | Out-Null
  Write-Host ('DIRETORIO_ISOLADO=' + $taskRoot)
  [IO.File]::WriteAllBytes((Join-Path $taskRoot 'observer.cjs'),[Convert]::FromBase64String(''))
  [IO.File]::WriteAllBytes((Join-Path $taskRoot 'prepare.mjs'),[Convert]::FromBase64String(''))
  [IO.File]::WriteAllBytes((Join-Path $taskRoot 'observer.test.mjs'),[Convert]::FromBase64String(''))
  Run-Checked -Program node -Arguments @('--test', (Join-Path $taskRoot 'observer.test.mjs'))
  $sourceRoot = Join-Path $taskRoot 'evolution'
  Run-Checked -Program git -Arguments @('clone','--config','core.autocrlf=false','--depth','1','--branch','2.3.7','https://github.com/EvolutionAPI/evolution-api.git',$sourceRoot)
  $candidate = Join-Path $taskRoot 'candidate.ts'
  Run-Checked -Program node -Arguments @((Join-Path $taskRoot 'prepare.mjs'),$sourceRoot,$candidate)
  Copy-Item -LiteralPath $candidate -Destination (Join-Path $sourceRoot 'src/api/integrations/channel/whatsapp/whatsapp.baileys.service.ts')
  Push-Location $sourceRoot
  try {
    Run-Checked -Program npm.cmd -Arguments @('ci','--ignore-scripts','--no-audit','--no-fund')
    # Apenas geracao local do client. O script abaixo nao chama migrate/deploy.
    $generatePath = Join-Path $taskRoot 'generate-client.cjs'
    $generateSource = @'
const { spawnSync } = require('node:child_process');
const r = spawnSync(process.execPath, ['node_modules/prisma/build/index.js', 'generate', '--schema', 'prisma/postgresql-schema.prisma'], { stdio: 'inherit', env: { ...process.env, DATABASE_CONNECTION_URI: 'postgresql://unused:unused@127.0.0.1:1/unused' } });
process.exit(r.status === null ? 1 : r.status);
'@
    [IO.File]::WriteAllText($generatePath, $generateSource, [Text.UTF8Encoding]::new($false))
    Run-Checked -Program node -Arguments @($generatePath)
    Run-Checked -Program npm.cmd -Arguments @('run','build')
  } finally { Pop-Location }
  $context = Join-Path $taskRoot 'image'
  New-Item -ItemType Directory -Path $context | Out-Null
  Copy-Item -LiteralPath (Join-Path $sourceRoot 'dist') -Destination (Join-Path $context 'dist') -Recurse
  $dockerfile = @'
FROM evoapicloud/evolution-api@sha256:1bd8afc4a6cf48822e6cf02469aeae7bd35a12a6b616eacd1291926307f4d339
WORKDIR /evolution
COPY dist/ ./dist/
ENTRYPOINT ["node", "dist/main.js"]
CMD []
'@
  [IO.File]::WriteAllText((Join-Path $context 'Dockerfile'),$dockerfile,[Text.UTF8Encoding]::new($false))
  $tag = 'm1m-tf3a-origin:review-' + (Get-Date -Format 'yyyyMMddHHmmss')
  Run-Checked -Program docker -Arguments @('build','--pull=false','--tag',$tag,$context)
  Write-Host ('IMAGEM_LOCAL=' + $tag)
  Run-Checked -Program docker -Arguments @('image','inspect','--format','ImageID={{.Id}} OS={{.Os}} Architecture={{.Architecture}} Entrypoint={{json .Config.Entrypoint}}',$tag)
  Write-Host 'RESULTADO=BUILD_LOCAL_APROVADO_SEM_INICIAR_CONTAINER'
  Write-Host 'Nao houve push, deploy, migration, conexao WhatsApp ou alteracao do projeto existente.'
} catch {
  Write-Host ('RESULTADO=INTERROMPIDO: ' + $_.Exception.Message)
  exit 1
} finally {
  Write-Host ('RELATORIO=' + $report)
  Stop-Transcript | Out-Null
}
